// Deterministically resolve the negotiation into a compact, factual context.
// The LLM never touches raw UUIDs, cents, or joins -- only writes prose.
const inJson = $input.first().json;
const body = inJson.body || inJson;            // webhook wraps POST body under .body
const fx = body.fixture || body;               // accept {fixture:{...}} or the fixture directly

const members = fx.members || [];
const categories = fx.categories || [];
const budgetItems = fx.budget_items || [];
const proposals = fx.proposals || [];
const currency = (fx.household && fx.household.currency_code) || 'USD';

const memById = {}; members.forEach(m => memById[m.id] = m);
const memByRole = {}; members.forEach(m => memByRole[m.role] = m);
const catById = {}; categories.forEach(c => catById[c.id] = c);
const biById = {}; budgetItems.forEach(b => biById[b.id] = b);

const money = (minor) => (typeof minor === 'number' ? minor / 100 : null);

// Pick the target proposal: explicit id > last 'agreed' > last overall.
let proposal = null;
const wantedId = body.proposal_id || fx.proposal_id;
if (wantedId) proposal = proposals.find(p => p.id === wantedId) || null;
if (!proposal) { for (let i = proposals.length - 1; i >= 0; i--) { if (proposals[i].status === 'agreed') { proposal = proposals[i]; break; } } }
if (!proposal && proposals.length) proposal = proposals[proposals.length - 1];

const rawChanges = (proposal && proposal.changes) || [];
const changes = rawChanges.map(ch => {
  const bi = biById[ch.budget_item_id] || {};
  const mem = memById[bi.member_id] || {};
  const cat = catById[bi.category_id] || {};
  const delta = money(ch.delta_amount_minor);
  return {
    role: mem.role || null,
    name: mem.display_name || null,
    member_id: bi.member_id || null,
    category: cat.name || null,
    month: bi.month || (proposal && proposal.month) || null,
    delta: delta,
    before: money(ch.amount_before_minor),
    after: money(ch.amount_after_minor),
    direction: (delta == null ? null : (delta < 0 ? 'reduced' : 'increased'))
  };
});

const proposerMem = (proposal && memById[proposal.proposer_member_id]) || {};
const requiredIds = (proposal && proposal.required_responder_member_ids) || [];

function roleSummary(role) {
  const mem = memByRole[role] || {};
  const mine = changes.filter(c => c.member_id && c.member_id === mem.id);
  return {
    role: role,
    name: mem.display_name || null,
    member_id: mem.id || null,
    is_proposer: !!(proposal && mem.id && proposal.proposer_member_id === mem.id),
    is_required_responder: !!(mem.id && requiredIds.indexOf(mem.id) !== -1),
    involved: mine.length > 0,
    cuts: mine.filter(c => c.direction === 'reduced'),
    additions: mine.filter(c => c.direction === 'increased')
  };
}

const goal = fx.goal ? {
  name: fx.goal.name,
  target: money(fx.goal.target_amount_minor),
  saved: money(fx.goal.saved_amount_minor),
  remaining: (money(fx.goal.target_amount_minor) != null && money(fx.goal.saved_amount_minor) != null)
    ? money(fx.goal.target_amount_minor) - money(fx.goal.saved_amount_minor) : null,
  target_date: fx.goal.target_date
} : null;

const context = {
  found_proposal: !!proposal,
  currency: currency,
  month: proposal ? proposal.month : null,
  status: proposal ? proposal.status : null,
  proposal_description: proposal ? (proposal.description || null) : null,
  proposal_rationale: proposal ? (proposal.ai_rationale || null) : null,
  proposer: { role: proposerMem.role || null, name: proposerMem.display_name || null, member_id: proposerMem.id || null },
  goal: goal,
  household_context: fx.household ? (fx.household.ai_context_text || null) : null,
  changes: changes,
  members: {
    parent_1: roleSummary('parent_1'),
    parent_2: roleSummary('parent_2'),
    teen_1: roleSummary('teen_1')
  }
};

return [{ json: context }];

// Guarantee the exact same output shape every call. IDs/roles/names come
// deterministically from the resolved context; the LLM only supplied 'message'.
const out = ($input.first().json && ($input.first().json.output || $input.first().json)) || {};
const ctx = $('Prepare Negotiation Context').first().json || {};
const membs = ctx.members || {};

function build(roleKey, outKey) {
  const m = membs[roleKey] || {};
  const src = out[outKey] || {};
  return {
    role: roleKey,
    member_id: m.member_id || null,
    name: m.name || null,
    involved: !!m.involved,
    is_proposer: !!m.is_proposer,
    message: (typeof src.message === 'string' && src.message.trim()) ? src.message.trim() : ''
  };
}

return [{
  json: {
    ok: true,
    month: ctx.month || null,
    status: ctx.status || null,
    currency: ctx.currency || 'USD',
    parent1: build('parent_1', 'parent1'),
    parent2: build('parent_2', 'parent2'),
    teen1: build('teen_1', 'teen1')
  }
}];
